def scene(r,id,x,bad,good):
    return f'<section class="pgs r-sc" id="{id}"><div class="wrap"><div class="r-hd"><span class="r-n">{x["n"]}</span><h2>{x["h"]}</h2><p>{x["p"]}</p></div><div class="cmp">{bad}<span class="vs">VS</span>{good}</div></div></section>'
def body(lg,wa,s_,crumb,_):
    r=X[lg];ar=lg=='ar';arw='↖'if ar else'↗';m=r['m'];b=r['b'];o=r['o'];ch=lambda t:f'<div class="chat">{t}</div>'
