    good=stage(r['af'],'good',view(0,3,bar(r['rn'])+ch(s('bb me',.3,None,m['q'])+inc('lk',1.2,None,f'<b>{r["rn"]}</b><small>{m["ls"]}</small>')))+view(3,None,bar(r['rn'])+'<div class="mn"><div class="se">'+m['se']+'</div><div class="cats"><i class="a">'+CT[lg][0]+'</i><i>'+CT[lg][1]+'</i><i>'+CT[lg][2]+'</i></div><div class="scw"><div class="sx slist" data-t="6.4" data-o="9"><div class="scl">'+''.join(s('ds',3.3+.3*i,None,f'<u class="u{i%4}"></u><span>{a_}</span><b>{p_}</b>')for i,(a_,p_)in enumerate(m['d']+EX[lg]))+'</div></div></div></div>'),m['cg'],9,4.4)
    s1=scene(r,'sc-menu',m,bad,good)
