    bad=stage(r['bf'],'bad',view(0,None,bar(r['rn'])+ch(''.join(s('bb me',.3+.9*i,None,t)for i,t in enumerate(b['m']))+s('nt',4,None,''.join(f'<p>{t}</p>'for t in b['nt']))+s('stamp',6,None,b['lost']))),b['cb'],11,6.6)
