    good=stage(r['af'],'good',view(0,4,bar(o['gt'])+'<div class="od">'+it+s('nn',1.2,None,o['nn'])+s('go',2,None,o['sn'])+'</div>')+view(4,7.2,bar(o['wt'])+'<div class="rc">'+s('card',4.4,None,'<small>'+o['nw']+'</small>'+it+'<small>'+o['nn']+'</small><div class="bt">'+sw(f'<i class="pb">{o["cf"]}</i>',f'<i class="dn">{o["cd"]}</i>',6.4)+'</div>')+'</div>')+view(7.2,None,bar(o['gt'])+f'<ol class="sp">{steps}</ol>')+s('bn',3.9,5.8,'<b>'+o['wt']+'</b><span>'+o['nw']+' · '+o['it'][0]+', '+o['it'][1]+'</span>'),o['cg'],12,8)
